import{_ as t,o,c as a,a2 as n}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Core Features & Tools","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md"}'),r={name:"guide/features.md"};function s(i,e,l,d,c,u){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="core-features-tools" tabindex="-1">Core Features &amp; Tools <a class="header-anchor" href="#core-features-tools" aria-label="Permalink to &quot;Core Features &amp; Tools&quot;">​</a></h1><hr><h2 id="screenshot-studio" tabindex="-1">📸 Terminal Screenshot Studio <a class="header-anchor" href="#screenshot-studio" aria-label="Permalink to &quot;📸 Terminal Screenshot Studio {#screenshot-studio}&quot;">​</a></h2><p>Capture Carbon.sh-style aesthetic terminal snapshots with custom backgrounds, shadows, and branding:</p><ul><li><strong>Quick Dropdown</strong>: Click <strong>Screenshot</strong> in the top tab bar to instantly <strong>Copy to Clipboard</strong> or <strong>Save to Computer</strong>.</li><li><strong>Screenshot Studio Modal</strong>: Open the full studio to customize: <ul><li><strong>Background Gradient</strong>: Toggle on/off or choose between <em>Indigo</em>, <em>Slate</em>, <em>Cyber</em>, <em>Sunset</em>, <em>Emerald</em>, <em>Rose</em>, <em>Obsidian</em>, and <em>Transparent</em>.</li><li><strong>Canvas Padding</strong>: Adjust padding dynamically (<code>0px</code> tight crop, <code>16px</code>, <code>36px</code>, <code>56px</code>).</li><li><strong>Window Controls</strong>: Toggle macOS traffic light buttons (Red, Yellow, Green).</li><li><strong>Native Save Dialog</strong>: Interactively browse and choose your target folder on your computer.</li><li><strong>Branding Watermark</strong>: Permanent multi-line branding watermark with the TermBolt logo:<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TermBolt (0.1.0)</span></span>
<span class="line"><span>termbolt.tahirjan.com</span></span></code></pre></div></li></ul></li></ul><hr><h2 id="system-fonts" tabindex="-1">🔤 Dynamic System Font Management <a class="header-anchor" href="#system-fonts" aria-label="Permalink to &quot;🔤 Dynamic System Font Management {#system-fonts}&quot;">​</a></h2><p>TermBolt avoids hardcoded font lists and queries all fonts installed on your computer dynamically via the <strong>System Font Repository Pattern</strong>:</p><ul><li><strong>Windows</strong>: Queries the Windows Registry (<code>HKLM</code> &amp; <code>HKCU</code> Fonts) and <code>%WINDIR%\\Fonts</code>.</li><li><strong>macOS</strong>: Reads <code>/System/Library/Fonts</code>, <code>/Library/Fonts</code>, and <code>~/Library/Fonts</code>.</li><li><strong>Linux</strong>: Scans via <code>fontconfig</code> (<code>fc-list</code>) and <code>/usr/share/fonts</code>.</li><li><strong>Smart Grouping</strong>: Automatically categorizes fonts into <strong>Monospace Fonts</strong> (e.g. <code>Cascadia Code</code>, <code>Fira Code</code>, <code>JetBrains Mono</code>, <code>Consolas</code>, Nerd Fonts) and <strong>All Installed System Fonts</strong>.</li><li><strong>Custom Font Mode</strong>: Easily toggle to manual text entry to specify any bespoke font name.</li></ul><hr><h2 id="master-vault" tabindex="-1">🔒 Encrypted Master Vault <a class="header-anchor" href="#master-vault" aria-label="Permalink to &quot;🔒 Encrypted Master Vault {#master-vault}&quot;">​</a></h2><ul><li><strong>Zero-Knowledge Encryption</strong>: Your server passwords and SSH private keys are never stored in plaintext. They are protected using <strong>PBKDF2 SHA-256 (100,000 iterations)</strong> and authenticated <strong>AES-256-GCM</strong> encryption.</li><li><strong>Auto-Lock Security</strong>: Automatically locks credential access after inactivity.</li></ul><hr><h2 id="cloud-sync" tabindex="-1">☁️ End-to-End Encrypted Cloud Sync <a class="header-anchor" href="#cloud-sync" aria-label="Permalink to &quot;☁️ End-to-End Encrypted Cloud Sync {#cloud-sync}&quot;">​</a></h2><ul><li><strong>Cryptographic Binary Snapshots</strong>: Export your entire server fleet, folders, snippets, and button bars into a <code>.termbolt</code> binary snapshot encrypted with AES-256-GCM.</li><li><strong>Google Drive Integration</strong>: Connect your Google account with OAuth 2.0 PKCE loopback authentication.</li><li><strong>Interactive Conflict Resolver</strong>: Compare local vs remote versions and resolve conflicts per item during snapshot restoration.</li></ul><hr><h2 id="sftp-manager" tabindex="-1">📂 Dual-Pane SFTP File Manager <a class="header-anchor" href="#sftp-manager" aria-label="Permalink to &quot;📂 Dual-Pane SFTP File Manager {#sftp-manager}&quot;">​</a></h2><ul><li><strong>Integrated Filesystem Navigation</strong>: Manage local and remote files simultaneously with directory breadcrumbs.</li><li><strong>Batch Transfer Queue</strong>: Upload and download files with real-time transfer progress notifications.</li><li><strong>Directory Traversal</strong>: Double-click folders or <code>..</code> to move up the directory hierarchy.</li></ul>`,18)])])}const h=t(r,[["render",s]]);export{m as __pageData,h as default};
